function futureISO(days,hour=10){const d=new Date();d.setHours(hour,0,0,0);d.setDate(d.getDate()+days);return d.toISOString()}
function monthKey(iso){const d=new Date(iso);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function dateText(iso){return new Date(iso).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}
function shortTime(iso){return new Date(iso).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function uid(prefix='id'){return `${prefix}-${(crypto.randomUUID?crypto.randomUUID():Date.now()+Math.random().toString(16).slice(2))}`}
function initials(name='Neighbour'){return name.trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function titleCase(v=''){return v.replace(/\b\w/g,m=>m.toUpperCase())}
function clone(v){return JSON.parse(JSON.stringify(v))}
function moneySafe(v){return esc(v||'Ask for a quote')}
function code4(){return String(Math.floor(1000+Math.random()*9000))}
function normPhone(v=''){return String(v).replace(/\D/g,'')}
function saE164(v=''){const d=normPhone(v);if(d.startsWith('27')&&d.length===11)return `+${d}`;if(d.startsWith('0')&&d.length===10)return `+27${d.slice(1)}`;return v.trim().startsWith('+')?v.trim():`+${d}`}
function upsertServerAccount(bundle){if(!bundle?.profile)return null;const p=bundle.profile,provider=bundle.provider||null;let a=state.accounts.find(x=>x.id===p.user_id);const next={id:p.user_id,role:p.role,first:p.first_name,last:p.last_name,email:bundle.email||a?.email||'',phone:p.mobile_e164||'',area:p.area||'',emailVerified:true,mobileVerified:!!a?.mobileVerified,identityVerified:p.identity_status==='verified',createdAt:a?.createdAt||Date.now(),accountStatus:p.account_status,ageGatePassed:!!p.age_gate_passed,serverBacked:true};if(provider)next.providerId=provider.provider_code;if(a)Object.assign(a,next);else{a=next;state.accounts.push(a)}if(provider){let lp=state.providers.find(x=>x.providerId===provider.provider_code);const mapped={id:lp?.id||uid('prov'),providerId:provider.provider_code,serverUserId:p.user_id,name:`${p.first_name} ${p.last_name}`,area:p.area||'',category:provider.category||'',service:provider.service_name||'',price:provider.price_from_cents==null?'Ask for a quote':`From R${(provider.price_from_cents/100).toFixed(0)}`,rating:lp?.rating||0,reviews:lp?.reviews||0,verified:provider.approval_status==='approved',identityVerified:p.identity_status==='verified',about:provider.about||'',areas:provider.areas||[],availability:provider.availability||'',status:provider.approval_status==='approved'?'approved':provider.approval_status,applicationStatus:provider.approval_status,credentialVerified:provider.credential_status==='verified',categoryVerified:provider.category_status==='verified',siteVisitRequired:lp?.siteVisitRequired||false,siteVisitDone:lp?.siteVisitDone||false,onboardingPassed:!!provider.onboarding_passed,badges:lp?.badges||[],membership:titleCase(provider.membership_tier||'start'),boosts:provider.boosts_balance||0,pricingMode:provider.pricing_mode||'quote_required',priceFromCents:provider.price_from_cents,paused:false,hideFromSearch:!!provider.hidden_from_search,applicationUpdates:lp?.applicationUpdates||[],gallery:lp?.gallery||[],membershipBreakHistory:lp?.membershipBreakHistory||[],serverBacked:true};if(lp)Object.assign(lp,mapped);else state.providers.push(mapped)}return a}
function daysUntil(iso){return Math.max(0,Math.ceil((new Date(iso).getTime()-Date.now())/86400000))}
function mapServerOrder(row){
 const existing=state.requests.find(r=>r.id===row.id);
 const provider=state.providers.find(p=>p.serverUserId===row.provider_id);
 const customer=state.accounts.find(a=>a.id===row.customer_id);
 return {
  ...(existing||{}),id:row.id,customerId:row.customer_id,providerUserId:row.provider_id,
  providerId:row.provider_code||provider?.providerId||existing?.providerId||'',providerName:row.provider_display_name||provider?.name||existing?.providerName||'Service provider',
  customerName:row.customer_display_name||(customer?`${customer.first} ${customer.last}`:(existing?.customerName||'Customer')),customerArea:row.customer_area||existing?.customerArea||'',
  service:row.service_name,scope:row.scope||'',note:row.scope||'',serviceAddress:existing?.serviceAddress||'',
  date:row.scheduled_at||row.created_at,scheduledAt:row.scheduled_at,expectedPrice:row.base_price_cents==null?'':`R${(row.base_price_cents/100).toFixed(0)}`,
  expectedPriceCents:row.base_price_cents,priceItemId:row.price_item_id||null,pricingModeAtBooking:row.pricing_mode_at_booking||null,priceProposedAt:row.price_proposed_at||null,priceConfirmedAt:row.price_confirmed_at||null,priceProposedBy:row.price_proposed_by||null,status:row.status,providerMarkedDone:!!row.provider_marked_done_at,
  providerMarkedDoneAt:row.provider_marked_done_at||null,customerConfirmedAt:row.customer_confirmed_at||null,
  createdAt:new Date(row.created_at).getTime(),updatedAt:new Date(row.updated_at||row.created_at).getTime(),serverBacked:true,
  messages:existing?.messages||[],extraWork:existing?.extraWork||null,safetyTimers:existing?.safetyTimers||{},checkins:existing?.checkins||{}
 };
}
async function syncServerOrders(){
 const a=currentAccount();if(!a?.serverBacked||!window.NeighbourlyAPI?.configured)return;
 try{
  const rows=await window.NeighbourlyAPI.listOrders();
  const mapped=rows.map(mapServerOrder);
  const locations=await window.NeighbourlyAPI.listOrderLocations();
  for(const r of mapped){const loc=locations.find(x=>x.order_id===r.id);if(loc)r.serviceAddress=loc.service_address}
  const ids=mapped.map(r=>r.id);
  const extras=await window.NeighbourlyAPI.listExtraWork(ids);
  for(const r of mapped){
   const latest=extras.filter(e=>e.order_id===r.id).sort((x,y)=>new Date(y.created_at)-new Date(x.created_at))[0];
   if(latest)r.extraWork={id:latest.id,description:latest.description,addedCost:latest.added_cost_cents==null?'':(latest.added_cost_cents/100).toFixed(0),addedCostCents:latest.added_cost_cents,status:latest.status,proposedBy:latest.proposed_by,serverBacked:true};
  }
  state.requests=state.requests.filter(r=>!r.serverBacked||!ids.includes(r.id));
  state.requests.push(...mapped);persist();
 }catch(e){console.error('Order sync failed',e);}
}
async function runServerServiceAction(r,action,opts={}){
 if(!r?.serverBacked)return false;
 try{await window.NeighbourlyAPI.serviceAction({orderId:r.id,action,extraWorkId:opts.extraWorkId||null,reason:opts.reason||null,basePriceCents:opts.basePriceCents??null,addedCostCents:opts.addedCostCents??null,timingNote:opts.timingNote||null});await syncServerOrders();render();return true}catch(e){console.error('Service action failed',e);toast(e?.message||'Could not update this service. Please try again.');return true}
}
async function syncServerProviders(){const a=currentAccount();if(!a?.serverBacked||!window.NeighbourlyAPI?.configured)return;try{const rows=await window.NeighbourlyAPI.listApprovedProviders();const items=await window.NeighbourlyAPI.listProviderPriceItems(rows.map(x=>x.user_id));const byProvider=new Map();for(const item of items){if(!byProvider.has(item.provider_id))byProvider.set(item.provider_id,[]);byProvider.get(item.provider_id).push(item)}for(const row of rows){let p=state.providers.find(x=>x.providerId===row.provider_code);const mapped={id:p?.id||uid('prov'),providerId:row.provider_code,serverUserId:row.user_id,name:row.display_name||'Neighbourly provider',area:row.primary_area||'',category:row.category||'',service:row.service_name||'',price:row.pricing_mode==='quote_required'?'Ask for a quote':row.price_from_cents==null?'Ask for a quote':`From R${(row.price_from_cents/100).toFixed(0)}`,priceCents:row.price_from_cents,rating:p?.rating||0,reviews:p?.reviews||0,verified:true,identityVerified:true,about:row.about||'',areas:row.areas||[],availability:row.availability||'',status:'approved',applicationStatus:'approved',onboardingPassed:!!row.onboarding_passed,badges:p?.badges||[],membership:titleCase(row.membership_tier||'start'),paused:false,hideFromSearch:false,gallery:p?.gallery||[],pricingMode:row.pricing_mode||'quote_required',priceItems:byProvider.get(row.user_id)||[],serverBacked:true};if(p)Object.assign(p,mapped);else state.providers.push(mapped)}persist()}catch(e){console.error('Provider sync failed',e)}}
async function syncMyMedia(){const a=currentAccount();if(!a?.serverBacked||!window.NeighbourlyAPI?.configured)return;try{const media=await window.NeighbourlyAPI.getMyMedia();a.profilePhotos=media.profile||[];const approved=(media.profile||[]).find(x=>x.review_status==='approved');if(approved)a.profilePhotoUrl=approved.url;const p=currentProvider();if(p)p.gallery=(media.portfolio||[]).map(x=>({id:x.id,dataUrl:x.url,caption:x.caption||'',reviewStatus:x.review_status,qualityStatus:x.quality_status,reviewNote:x.review_note||x.rejection_reason||'',isFeatured:!!x.is_featured,serverBacked:true}));persist()}catch(e){console.error('Media sync failed',e)}}
function startNotificationSubscription(){const a=currentAccount();window.NeighbourlyAPI?.unsubscribe?.(window.__notificationChannel);window.__notificationChannel=null;if(!a?.serverBacked||!window.NeighbourlyAPI?.subscribeNotifications)return;window.__notificationChannel=window.NeighbourlyAPI.subscribeNotifications(a.id,n=>{if((state.serverNotifications||[]).some(x=>x.id===n.id))return;state.serverNotifications=[n,...(state.serverNotifications||[])];persist();if(state.route==='updates')render();toast(n.title||'New Neighbourly update')})}
async function syncServerNotifications(){
 const a=currentAccount();if(!a?.serverBacked||!window.NeighbourlyAPI?.configured){state.serverNotifications=[];return}
 try{state.serverNotifications=await window.NeighbourlyAPI.listNotifications();persist()}catch(e){console.error('Notification sync failed',e)}
}
async function syncMembershipCatalog(){
 const a=currentAccount();if(!a?.serverBacked||a.role!=='provider'||!window.NeighbourlyAPI?.configured)return;
 try{state.membershipPlans=await window.NeighbourlyAPI.listMembershipPlans();state.myMembership=await window.NeighbourlyAPI.getMyMembership();persist()}catch(e){console.error('Membership sync failed',e)}
}

