function adminSettings(){return shell(`<section class="screen admin narrow">${topbar('Desk settings','Policy principles for the prototype.')}<div class="card policy-card"><h3>Community enforcement</h3><p>Account removal is the last normal step. Guidance, warnings and temporary restrictions should be proportionate to the behaviour. Severe safety issues can justify immediate protective restriction while reviewed.</p></div><div class="card policy-card"><h3>Food orders</h3><p>Food is not returnable for simple change of mind or taste preference once supplied. Genuine unsafe, incorrect or materially defective food concerns must still be handled fairly and applicable consumer rights remain.</p></div><div class="card policy-card"><h3>Identity & safety</h3><p>Customers and providers should be identity-verified before real-world services. Do not expose ID documents to other users. Production should use secure identity verification and minimal retention rather than storing raw ID copies indefinitely.</p></div><div class="card policy-card"><h3>Advertising</h3><p>Trust is earned. Reach can be purchased. Promotions must be clearly marked and cannot buy verification, ratings or trust badges.</p></div><div class="card policy-card"><h3>Production security boundary</h3><p>Real identity checks, payment controls, device-risk signals, background notifications and secure ban-evasion matching require the production backend. This prototype deliberately does not store raw ID copies.</p></div><div class="card policy-card"><h3>Audit trail</h3><p>Important admin decisions should record who acted, what changed, when and why. This prototype has ${state.auditLog?.length||0} recorded admin actions.</p></div><details class="info-drawer audit-drawer"><summary>View recent audit history <span>→</span></summary><div class="audit-list">${[...(state.auditLog||[])].sort((a,b)=>b.t-a.t).slice(0,20).map(x=>`<div><b>${esc(x.action)}</b><span>${dateText(x.t)} · ${esc(x.actor||'System')}</span><small>${esc(x.details||'No additional detail')}</small></div>`).join('')||'<p class="muted">No recorded actions yet.</p>'}</div></details><button class="btn secondary" data-action="signout">Close Sisters Help Desk</button></section>`,'adminSettings')}

function render(){const q=new URLSearchParams(location.search);if(q.get('admin')==='sisters'&&state.role!=='admin'&&state.route==='publicHome')state.route='adminLogin';const routes={publicHome,loginChoice,loginForm,joinChoice,joinCustomer:()=>baseSignup('customer'),joinProvider:()=>baseSignup('provider'),customerHome,customerTour,findHelp,customerFavourites,customerServices,providerHome,providerHow,providerApplication,providerRequests,providerCustomers,providerServices,providerFeatures,providerReady,sectionQuiz,categoryReady,categoryReadyQuiz,finalReadyIntro,finalReadyQuiz,providerGrowth,communityEvents,publicEvents:()=>communityEvents(true),updates,helpDesk,profile,adminLogin,adminHome,adminApplications,adminMediaReview,adminReports,adminPeople,adminEvents,adminAppeals,adminAnalytics,adminSettings};const customerRoutes=new Set(['customerHome','customerTour','findHelp','customerFavourites','customerServices']);const providerRoutes=new Set(['providerHome','providerHow','providerApplication','providerRequests','providerCustomers','providerServices','providerFeatures','providerReady','sectionQuiz','categoryReady','categoryReadyQuiz','finalReadyIntro','finalReadyQuiz','providerGrowth']);const adminRoutes=new Set(['adminHome','adminApplications','adminMediaReview','adminReports','adminPeople','adminEvents','adminAppeals','adminAnalytics','adminSettings']);if(customerRoutes.has(state.route)&&state.role!=='customer')state.route='publicHome';if(providerRoutes.has(state.route)&&state.role!=='provider')state.route='publicHome';if(adminRoutes.has(state.route)&&state.role!=='admin')state.route='adminLogin';if(['communityEvents','updates','helpDesk','profile'].includes(state.route)&&!state.role)state.route='publicHome';app.innerHTML=(routes[state.route]||publicHome)();bind();if(state.route==='findHelp')renderFindResults();if(state.route==='communityEvents')renderEventResults()}
function bind(){
 $$('[data-nav]').forEach(el=>el.addEventListener('click',()=>nav(el.dataset.nav)));
 $('#signupForm')?.addEventListener('submit',handleSignup);$('#loginForm')?.addEventListener('submit',handleLogin);$('#providerApplicationForm')?.addEventListener('submit',handleProviderApplication);$('#adminLoginForm')?.addEventListener('submit',handleAdminLogin);$('#sectionQuizForm')?.addEventListener('submit',handleSectionQuiz);$('#categoryQuizForm')?.addEventListener('submit',handleCategoryQuiz);$('#finalReadyForm')?.addEventListener('submit',handleFinalQuiz);
 $('#providerSearch')?.addEventListener('input',e=>{state.ui.search=e.target.value;persist();renderFindResults()});$('#categoryFilter')?.addEventListener('change',e=>{state.ui.category=e.target.value;persist();renderFindResults()});$('#areaFilter')?.addEventListener('change',e=>{state.ui.area=e.target.value;persist();renderFindResults()});
 $('#eventArea')?.addEventListener('change',e=>{state.ui.eventArea=e.target.value;persist();renderEventResults()});$('#eventCategory')?.addEventListener('change',e=>{state.ui.eventCategory=e.target.value;persist();renderEventResults()});$('#eventMonth')?.addEventListener('change',e=>{state.ui.eventMonth=e.target.value;persist();renderEventResults()});
 bindDynamic();
}
