async function handleSignup(e){
 e.preventDefault();
 const f=e.currentTarget,fd=new FormData(f),role=f.dataset.role,first=fd.get('first').trim(),last=fd.get('last').trim(),email=fd.get('email').trim().toLowerCase(),phone=fd.get('phone').trim(),area=fd.get('area').trim(),password=fd.get('password'),err=$('#signupError');
 if(!first||!last||!/^\S+@\S+\.\S+$/.test(email)||phone.replace(/\D/g,'').length<9||!area||password.length<8||!fd.get('ageGate')||!fd.get('community')){err.textContent='Almost there — complete every field, confirm you are 18+, and tick the community agreement.';err.classList.add('show');return}
 if(window.NeighbourlyAPI?.configured){
  try{
   const result=await window.NeighbourlyAPI.signUp({role,firstName:first,lastName:last,email,mobileE164:saE164(phone),area,password});
   state.loginRole=role;
   if(result.session){const bundle=await window.NeighbourlyAPI.getMyProfile(result.user.id);const a=upsertServerAccount(bundle);state.currentAccountId=a.id;state.role=a.role;state.route=a.role==='provider'?'providerHow':'customerTour';persist();render();toast(role==='provider'?'Provider account created':'Welcome to the neighbourhood ♥')}
   else{state.role=null;state.currentAccountId=null;state.route='loginForm';persist();render();modal('Check your email','Your account was created. Open the confirmation email from Neighbourly, confirm your address, then come back and log in.')}return;
  }catch(ex){console.error('Signup failed',ex);err.textContent=String(ex?.message||'').includes('already')?'That email may already be part of Neighbourly. Try logging in instead.':'We could not create the account right now. Check your details and try again.';err.classList.add('show');return}
 }
 if((state.bannedPeople||[]).some(b=>b.email===email||normPhone(b.phone)===normPhone(phone))){state.auditLog.push({t:Date.now(),action:'Blocked rejoin attempt',details:`${email} · ${normPhone(phone)}`,actor:'System'});persist();err.textContent='We can’t approve this signup automatically because these details match a permanently removed account. If you believe this is a mistake, use “Appeal a Neighbourly decision” on the home page.';err.classList.add('show');return}
 if(state.accounts.some(a=>a.email===email)){err.textContent='That email is already part of Neighbourly.';err.classList.add('show');return}
 const passwordHash=await hashText(password),id=uid('acct');const account={id,role,first,last,email,phone,area,passwordHash,emailVerified:false,mobileVerified:false,identityVerified:false,createdAt:Date.now(),accountStatus:'active',ageGatePassed:true};if(role==='provider'){account.providerId=uniqueProviderId();state.providers.push({id:uid('prov'),providerId:account.providerId,name:`${first} ${last}`,area,category:'',service:'',price:'Ask for a quote',rating:0,reviews:0,verified:false,identityVerified:false,about:'',areas:[area],availability:'',status:'pending',applicationStatus:null,credentialVerified:false,categoryVerified:false,siteVisitRequired:false,siteVisitDone:false,onboardingPassed:false,badges:[],membership:'Start',boosts:0,paused:false,applicationUpdates:[],gallery:[],membershipBreakHistory:[]})}state.accounts.push(account);state.currentAccountId=id;state.role=role;state.route=role==='provider'?'providerHow':'customerTour';persist();render();toast(role==='provider'?'Provider account created ':'Welcome to the neighbourhood ♥')
}
async function handleLogin(e){
 e.preventDefault();const fd=new FormData(e.currentTarget),identifier=fd.get('identifier').trim().toLowerCase(),password=fd.get('password'),err=$('#loginError');
 if(window.NeighbourlyAPI?.configured){
  if(!/^\S+@\S+\.\S+$/.test(identifier)){err.textContent='Enter the email address you used for Neighbourly.';err.classList.add('show');return}
  try{const result=await window.NeighbourlyAPI.signIn({email:identifier,password});const a=upsertServerAccount(result.account);if(a.accountStatus==='permanently_removed'){await window.NeighbourlyAPI.signOut();throw new Error('account-removed')}state.currentAccountId=a.id;state.role=a.role;state.route=a.role==='provider'?'providerHome':'customerHome';persist();await syncServerProviders();await syncMyMedia();await syncMembershipCatalog();render();startNotificationSubscription();openSharedProviderIfReady();toast(`Welcome back, ${a.first}`);return}catch(ex){console.error('Login failed',ex);err.textContent=String(ex?.message||'').includes('account-removed')?'This account was permanently removed. If you believe this was a mistake, use the appeal option on the Neighbourly home page.':'We couldn’t match those details. Check your email and password, confirm your email if you just joined, and try again.';err.classList.add('show');return}
 }
 const hash=await hashText(password);let a=state.accounts.find(x=>(x.email===identifier||(x.providerId&&x.providerId.toLowerCase()===identifier))&&x.role===state.loginRole);if(!a||!((a.demoPassword&&password===a.demoPassword)||(a.passwordHash&&a.passwordHash===hash))){err.textContent='We couldn’t match those details. Check them and try again.';err.classList.add('show');return}if(a.accountStatus==='permanently_removed'){err.textContent='This account was permanently removed. If you believe this was a mistake, use the appeal option on the Neighbourly home page.';err.classList.add('show');return}state.currentAccountId=a.id;state.role=a.role;state.route=a.role==='provider'?'providerHome':'customerHome';persist();render();toast(`Welcome back, ${a.first}`)
}
function handleProviderApplication(e){e.preventDefault();const p=currentProvider(),fd=new FormData(e.currentTarget),required=['category','service','about','areas','availability','experience','credentialPath'];if(required.some(k=>!fd.get(k)?.trim())||!fd.get('agree')){$('#applicationError').textContent='Please complete each section and tick the agreement.';$('#applicationError').classList.add('show');return}Object.assign(p,{category:fd.get('category'),service:fd.get('service').trim(),about:fd.get('about').trim(),price:fd.get('price').trim()||'Ask for a quote',areas:fd.get('areas').split(',').map(x=>x.trim()).filter(Boolean),availability:fd.get('availability').trim(),experience:fd.get('experience').trim(),credentialPath:fd.get('credentialPath'),applicationStatus:'submitted',status:'pending',siteVisitRequired:fd.get('category')==='Food'});p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:'Application submitted'});persist();nav('providerHome');toast('Application saved — Neighbourly Ready is next')}
