function handleSectionQuiz(e){e.preventDefault();const t=trainingState(),sec=trainingSections[t.section],fd=new FormData(e.currentTarget),critical=SECTION_CRITICAL[sec.id]||[];let score=0,criticalOk=true;const missed=[],answers={};for(let i=0;i<sec.questions.length;i++){if(fd.get(`q${i}`)===null){$('#quizError').textContent='Answer each question before checking.';$('#quizError').classList.add('show');return}const ans=Number(fd.get(`q${i}`));answers[i]=ans;const correct=ans===sec.questions[i][2];if(correct)score++;else missed.push(i);if(critical.includes(i)&&!correct)criticalOk=false}const passed=score/sec.questions.length>=.8&&criticalOk;t.sectionAnswers=t.sectionAnswers||{};t.sectionAnswers[sec.id]=answers;t.sectionPassed[sec.id]=passed;t.lastSectionResult={score,total:sec.questions.length,passed,criticalOk,missed};persist();app.innerHTML=sectionResult(score,sec.questions.length,passed);bindDynamic()}
function handleFinalQuiz(e){e.preventDefault();const t=trainingState(),fd=new FormData(e.currentTarget);let score=0,criticalOk=true;t.finalAnswers={};const missed=[];for(let i=0;i<finalQuestions.length;i++){if(fd.get(`q${i}`)===null){$('#finalQuizError').textContent='Answer all 15 questions before checking.';$('#finalQuizError').classList.add('show');return}const ans=Number(fd.get(`q${i}`));t.finalAnswers[i]=ans;const correct=ans===finalQuestions[i][2];if(correct)score++;else missed.push(i);if(finalQuestions[i][3]&&!correct)criticalOk=false}const passed=score>=12&&criticalOk;t.finalPassed=passed;t.lastFinal={score,criticalOk,passed,missed};persist();app.innerHTML=finalReadyResult(score,criticalOk,passed);bindDynamic()}



function messageThread(r){const msgs=r.messages||[];if(!msgs.length)return'';return `<div class="message-thread"><b>Messages</b>${msgs.slice(-3).map(m=>`<p><strong>${esc(m.fromName||'Neighbour')}:</strong> ${esc(m.text)}</p>`).join('')}</div>`}
async function messageModal(requestId){
 const r=state.requests.find(x=>x.id===requestId),a=currentAccount();if(!r||!a)return;
 if(r.serverBacked&&window.NeighbourlyAPI?.configured){
  try{
   const rows=await window.NeighbourlyAPI.listMessages(r.id);
   const nameFor=id=>id===a.id?'You':(a.role==='customer'?(r.providerName||'Service provider'):(r.customerName||'Customer'));
   const thread=()=>`<div id="liveMessageThread" class="message-thread"><b>Messages</b>${rows.length?rows.map(m=>`<p data-message-id="${esc(m.id)}"><strong>${esc(nameFor(m.sender_id))}:</strong> ${esc(m.body)}</p>`).join(''):'<p class="muted">No messages yet.</p>'}</div>`;
   formModal('Service messages',`${thread()}<div class="field"><label>Message<textarea name="message" maxlength="2000" required placeholder="Keep it clear and useful."></textarea></label></div><button class="btn primary" type="submit">Send message</button>`,async fd=>{const text=fd.get('message').trim();if(!text)return;try{const sent=await window.NeighbourlyAPI.sendMessage(r.id,text);if(!rows.some(m=>m.id===sent.id))rows.push(sent);closeModal();toast('Message sent');setTimeout(()=>messageModal(requestId),80)}catch(e){console.error('Message send failed',e);toast('Message could not be sent. Check your connection and try again.')}});
   window.NeighbourlyAPI.unsubscribe?.(window.__messageChannel);window.__messageChannel=window.NeighbourlyAPI.subscribeMessages(r.id,m=>{if(rows.some(x=>x.id===m.id))return;rows.push(m);const box=$('#liveMessageThread');if(box){box.querySelector('.muted')?.remove();box.insertAdjacentHTML('beforeend',`<p data-message-id="${esc(m.id)}"><strong>${esc(nameFor(m.sender_id))}:</strong> ${esc(m.body)}</p>`);box.scrollTop=box.scrollHeight}});return;
  }catch(e){console.error('Message load failed',e);toast('Messages could not load. Check your connection and try again.');return}
 }
 formModal('Service messages',`${messageThread(r)||'<div class="soft-note">No messages yet.</div>'}<div class="field"><label>Message<textarea name="message" maxlength="500" required placeholder="Keep it clear and useful."></textarea></label></div><button class="btn primary" type="submit">Send message</button>`,fd=>{const text=fd.get('message').trim();if(!text)return;r.messages=r.messages||[];r.messages.push({id:uid('msg'),fromId:a.id,fromName:`${a.first} ${a.last}`,text,t:Date.now()});persist();closeModal();render();toast('Message sent')})
}
function cancelBookingModal(requestId){const r=state.requests.find(x=>x.id===requestId),a=currentAccount();if(!r||!a||!['accepted','in_progress'].includes(r.status))return;formModal('Cancel booking',`<p class="muted">Cancel as early as reasonably possible. Genuine emergencies are considered fairly; repeated avoidable cancellations may affect reliability.</p><div class="field"><label>Reason<select name="reason" required><option value="">Choose one</option><option>Schedule changed</option><option>Emergency</option><option>Unable to complete the service</option><option>Customer/provider requested a change</option><option>Other</option></select></label></div><div class="field"><label>Short note<textarea name="note" maxlength="300"></textarea></label></div><button class="btn danger" type="submit">Cancel booking</button>`,async fd=>{if(!fd.get('reason'))return;const reason=`${fd.get('reason')}${fd.get('note').trim()?`: ${fd.get('note').trim()}`:''}`;if(r.serverBacked){closeModal();await runServerServiceAction(r,'cancel',{reason});toast('Booking cancelled');return}r.status='cancelled';r.cancelledBy=a.role;r.cancellationReason=fd.get('reason');r.cancellationNote=fd.get('note').trim();r.cancelledAt=Date.now();persist();closeModal();render();toast('Booking cancelled')})}
function membershipBreakNotice(p){if(!p?.membershipBreakUntil)return'';const left=daysUntil(p.membershipBreakUntil);return `<div class="card membership-break-notice"><div class="provider-top">${icon('pause')}<div><h3>Membership break</h3><p>Your profile is out of active search until ${dateText(p.membershipBreakUntil)}. ${left<=3?`Your break ends in ${left||'less than one'} day${left===1?'':'s'}.`:''}</p><small>Production billing will resume automatically on your return date.</small></div></div></div>`}
function safetyStatusBanner(r){const a=currentAccount(),t=a?(r.safetyTimers||{})[a.id]:null;if(!t||t.checkedOut)return'';return `<div class="${t.overdue?'danger-note':'safety-note'}"><b>${t.overdue?'Safety check-in due':'Safety timer set'}</b><span>${t.overdue?'Your expected finish time has passed. Open Safety tools when you are safe.':`Expected finish ${shortTime(t.expectedAt)}.`}</span></div>`}
function setSafetyTimerModal(requestId){const r=state.requests.find(x=>x.id===requestId),a=currentAccount();if(!r||!a)return;formModal('Expected finish time',`<p class="muted">Choose when you expect this service to finish. In the production app, Neighbourly can use this for opt-in safety reminders.</p><div class="field"><label>Expected finish<input name="finish" type="datetime-local" required></label></div><button class="btn primary" type="submit">Set safety time</button>`,fd=>{const d=new Date(fd.get('finish'));if(isNaN(d)||d.getTime()<=Date.now()){toast('Choose a future finish time');return}r.safetyTimers=r.safetyTimers||{};r.safetyTimers[a.id]={expectedAt:d.toISOString(),checkedOut:false,overdue:false};persist();closeModal();render();toast('Safety time set ✓')})}
async function shareProviderProfile(providerId){const p=state.providers.find(x=>x.providerId===providerId);if(!p)return;const url=`${location.origin}${location.pathname}?provider=${encodeURIComponent(p.providerId)}`;const text=`Meet ${p.name} on Neighbourly\n${p.service} · ${p.area}\nProvider ID: ${p.providerId}\n${url}`;try{if(navigator.share){await navigator.share({title:`${p.name} on Neighbourly`,text,url});toast('Provider profile shared')}else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('Provider link copied — ready to share')}else{modal('Share provider',text)}}catch(e){if(e?.name!=='AbortError')modal('Share provider',text)}}
async function shareNeighbourly(){const url=`${location.origin}${location.pathname}`;const text=`Neighbourly helps you find trusted local service providers, manage bookings and get real human support.\n${url}`;try{if(navigator.share){await navigator.share({title:'Neighbourly',text,url});toast('Neighbourly shared')}else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('Neighbourly link copied — ready to share')}else{modal('Share Neighbourly',text)}}catch(e){if(e?.name!=='AbortError')modal('Share Neighbourly',text)}}
