async function shareServiceDetails(requestId){const r=state.requests.find(x=>x.id===requestId),a=currentAccount();if(!r||!a)return;const p=state.providers.find(x=>x.providerId===r.providerId),counter=a.role==='customer'?p?.name:r.customerName,t=(r.safetyTimers||{})[a.id],text=`Neighbourly service details\nService: ${r.service}\nWith: ${counter||'Neighbourly member'}\nDate: ${dateText(r.date||r.createdAt)}\nArea: ${a.area||''}\nService Code: ${r.serviceCode||'Not created yet'}${t?`\nExpected finish: ${dateText(t.expectedAt)} ${shortTime(t.expectedAt)}`:''}`;try{if(navigator.share){await navigator.share({title:'Neighbourly service details',text});toast('Service details shared')}else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('Service details copied — ready to share')}else{modal('Service details',text)}}catch(e){if(e?.name!=='AbortError')modal('Service details',text)}finally{closeModal()}}
function trustedContactModal(){const a=currentAccount();if(!a)return;formModal('Trusted contact',`<p class="muted">Save one person you may want to share service details with. This is private to your account in this prototype.</p><div class="field"><label>Name<input name="name" maxlength="60" value="${esc(a.trustedContact?.name||'')}"></label></div><div class="field"><label>Mobile number<input name="phone" inputmode="tel" maxlength="25" value="${esc(a.trustedContact?.phone||'')}"></label></div><button class="btn primary" type="submit">Save trusted contact</button>`,fd=>{const name=fd.get('name').trim(),phone=fd.get('phone').trim();if(!name||normPhone(phone).length<9){toast('Add a name and valid mobile number');return}a.trustedContact={name,phone};persist();closeModal();render();toast('Trusted contact saved ✓')})}
function reportTargetOptions(a,context={}){const out=[{value:'general:',label:'General app or support issue'}];if(context.providerId){const p=state.providers.find(x=>x.providerId===context.providerId);if(p)out.push({value:`provider:${p.providerId}`,label:`Service provider: ${p.name}`})}if(context.eventId){const e=state.events.find(x=>x.id===context.eventId);if(e)out.push({value:`event:${e.id}`,label:`Community event: ${e.title}`})}if(context.requestId){const r=state.requests.find(x=>x.id===context.requestId);if(r&&a?.role==='customer'){const p=state.providers.find(x=>x.providerId===r.providerId);if(p)out.push({value:`provider:${p.providerId}`,label:`Service provider: ${p.name}`})}if(r&&a?.role==='provider'){const c=state.accounts.find(x=>x.id===r.customerId);if(c)out.push({value:`customer:${c.id}`,label:`Customer: ${c.first} ${c.last}`})}}
 if(a?.role==='customer'){const ids=[...new Set(state.requests.filter(r=>r.customerId===a.id).map(r=>r.providerId))];ids.forEach(id=>{const p=state.providers.find(x=>x.providerId===id);if(p&&!out.some(o=>o.value===`provider:${id}`))out.push({value:`provider:${id}`,label:`Service provider: ${p.name}`})})}
 if(a?.role==='provider'){const p=currentProvider(),ids=[...new Set(state.requests.filter(r=>r.providerId===p?.providerId).map(r=>r.customerId))];ids.forEach(id=>{const c=state.accounts.find(x=>x.id===id);if(c&&!out.some(o=>o.value===`customer:${id}`))out.push({value:`customer:${id}`,label:`Customer: ${c.first} ${c.last}`})})}
 (state.events||[]).filter(e=>e.status!=='removed').slice(0,20).forEach(e=>{if(!out.some(o=>o.value===`event:${e.id}`))out.push({value:`event:${e.id}`,label:`Community event: ${e.title}`})});return out}
function reportContextValue(context,a){if(context.providerId)return`provider:${context.providerId}`;if(context.eventId)return`event:${context.eventId}`;if(context.requestId){const r=state.requests.find(x=>x.id===context.requestId);if(r&&a?.role==='customer')return`provider:${r.providerId}`;if(r&&a?.role==='provider')return`customer:${r.customerId}`}return'general:'}
function resolveReportTarget(value){const [type,id='']=String(value||'general:').split(':');if(type==='provider'){const p=state.providers.find(x=>x.providerId===id),acct=state.accounts.find(x=>x.providerId===id);return{type:'account',id,label:p?`Service provider: ${p.name}`:'Service provider',accountId:acct?.id||null,providerId:id}}if(type==='customer'){const c=state.accounts.find(x=>x.id===id);return{type:'account',id,label:c?`Customer: ${c.first} ${c.last}`:'Customer',accountId:id}}if(type==='event'){const e=state.events.find(x=>x.id===id);return{type:'event',id,label:e?`Community event: ${e.title}`:'Community event'}}return{type:'general',id:'',label:'General app or support issue'}}
function closeReportGeneral(id){const r=state.reports.find(x=>x.id===id);if(!r)return;r.status='closed';r.outcome='Reviewed — no account action';audit('Case closed',r.id);persist();render();toast('Case marked reviewed')}
function removeEventFromReport(id){const r=state.reports.find(x=>x.id===id),e=state.events.find(x=>x.id===r?.targetId);if(!r||!e)return;e.status='removed';r.status='closed';r.outcome='Community event removed';audit('Community event removed',`${e.id} · report ${r.id}`);persist();render();toast('Event removed and case closed')}
function setEventVisibility(id,visible){const e=state.events.find(x=>x.id===id);if(!e)return;e.status=visible?'active':'removed';audit(visible?'Community event restored':'Community event removed',e.id);persist();render();toast(visible?'Event restored':'Event removed')}
function adminEvents(){const list=[...(state.events||[])].sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt));return shell(`<section class="screen admin">${topbar('Community events','Review and moderate community listings.')}<div class="stack">${list.length?list.map(e=>`<article class="card"><div class="request-head"><div><h3>${esc(e.title)}</h3><p>${esc(e.area)} · ${esc(e.category)} · ${dateText(e.startsAt)}</p></div>${statusPill(e.status==='removed'?'restricted':'approved')}</div><p class="muted">${esc(e.details)}</p><small>Listed by ${esc(e.createdBy||'Neighbourly member')}</small><div class="card-actions">${e.status==='removed'?`<button class="btn primary small" data-action="restoreEvent" data-id="${e.id}">Restore event</button>`:`<button class="btn danger small" data-action="removeEvent" data-id="${e.id}">Remove event</button>`}</div></article>`).join(''):`<div class="card empty"><h3>No upcoming events</h3></div>`}</div></section>`)}
function appealModal(){formModal('Appeal a Neighbourly decision',`<p class="muted">If you believe a permanent removal or blocked rejoin match was a mistake, you may ask the Sisters Help Desk for one fair review.</p><div class="field"><label>Email used on the account<input name="email" type="email" required></label></div><div class="field"><label>Mobile number<input name="phone" inputmode="tel" required></label></div><div class="field"><label>Why should we review the decision?<textarea name="details" maxlength="700" required></textarea></label></div><button class="btn primary" type="submit">Send appeal</button>`,fd=>{const email=fd.get('email').trim().toLowerCase(),phone=normPhone(fd.get('phone')),ban=(state.bannedPeople||[]).find(b=>b.email===email||normPhone(b.phone)===phone);if(!ban){toast('We could not match those details to a removed account. Please use Sisters Help Desk for general support.');return}if((state.appeals||[]).some(x=>x.banAccountId===ban.accountId&&x.status==='pending')){toast('An appeal for this account is already waiting for review.');return}state.appeals=state.appeals||[];state.appeals.push({id:uid('appeal'),banAccountId:ban.accountId,email,phone,details:fd.get('details').trim(),status:'pending',createdAt:Date.now()});persist();closeModal();toast('Appeal sent to Sisters Help Desk')})}
function adminAppeals(){const list=[...(state.appeals||[])].sort((a,b)=>b.createdAt-a.createdAt);return shell(`<section class="screen admin">${topbar('Appeals','One fair review for permanent-removal mistakes.')}<div class="stack">${list.length?list.map(a=>`<article class="card"><div class="request-head"><div><h3>${esc(a.email)}</h3><p>${dateText(a.createdAt)}</p></div>${statusPill(a.status==='pending'?'awaiting':a.status==='upheld'?'approved':'declined')}</div><p class="muted">${esc(a.details)}</p>${a.status==='pending'?`<div class="card-actions"><button class="btn primary small" data-action="appealAction" data-id="${a.id}" data-result="upheld">Uphold appeal</button><button class="btn secondary small" data-action="appealAction" data-id="${a.id}" data-result="declined">Decline appeal</button></div>`:`<div class="soft-note">Decision: ${esc(a.status)}</div>`}</article>`).join(''):`<div class="card empty"><h3>No appeals waiting</h3></div>`}</div></section>`)}
function appealAction(id,result){const a=state.appeals.find(x=>x.id===id);if(!a)return;a.status=result;a.decidedAt=Date.now();if(result==='upheld'){const ban=state.bannedPeople.find(b=>b.accountId===a.banAccountId),acct=state.accounts.find(x=>x.id===a.banAccountId);state.bannedPeople=state.bannedPeople.filter(b=>b.accountId!==a.banAccountId);if(acct){acct.accountStatus='active';const p=acct.providerId?state.providers.find(x=>x.providerId===acct.providerId):null;if(p){p.status='changes';p.applicationStatus='ready_for_review';p.hideFromSearch=true;p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:'Appeal upheld — application returned to Sisters Help Desk review'})}}audit('Appeal upheld',a.id)}else audit('Appeal declined',a.id);persist();render();toast(result==='upheld'?'Appeal upheld — account can be reviewed again':'Appeal declined')}
function categoryModuleFor(p){if(p?.category==='Food')return{title:'Food Provider Ready',screens:[['Food safety comes first','Food providers must be honest about how food is prepared, stored and supplied, and must complete any category checks required before approval.'],['Allergies and ingredients','Customers need clear, accurate information about ingredients or disclosed dietary requirements. Never guess about allergens.'],['Food complaints','A change of mind or taste preference is not the same as unsafe or incorrect food. Genuine safety or quality concerns must be taken seriously and handled fairly.'],['Verification may include a visit','The Sisters Help Desk may review documents, photos or arrange an appropriate food-operation visit before approval.']],questions:[['A customer asks about an allergen and you are unsure.',['Guess based on the recipe','Say you are unsure and verify before making a claim'],1],['Can a food provider go live before required food verification is complete?',['Yes','No'],1],['Is “I dislike the flavour” automatically the same as unsafe food?',['Yes','No'],1],['May Sisters Help Desk require an appropriate food-operation visit?',['Yes','No'],0]]};return null}
function categoryReady(){const p=currentProvider(),m=categoryModuleFor(p),t=trainingState();if(!m)return finalReadyIntro();t.categoryScreen=t.categoryScreen||0;const scr=m.screens[t.categoryScreen];return shell(`<section class="screen narrow">${topbar(m.title,`Extra section for ${esc(p.category)} providers`)}<div class="card training-card"><div class="lesson-icon">${icon('safety')}</div><span class="eyebrow">${t.categoryScreen+1} of ${m.screens.length}</span><h1>${esc(scr[0])}</h1><p>${esc(scr[1])}</p><div class="card-actions"><button class="btn secondary" data-action="categoryBack">Back</button><button class="btn primary" data-action="categoryNext">${t.categoryScreen===m.screens.length-1?'Quick Check':'Next'}</button></div></div></section>`)}
function categoryReadyQuiz(){const p=currentProvider(),m=categoryModuleFor(p);if(!m)return finalReadyIntro();return shell(`<section class="screen narrow">${topbar(m.title,'Quick Check')}<form id="categoryQuizForm" class="card form">${m.questions.map((q,i)=>`<fieldset style="border:0;padding:0"><legend style="font-weight:900">${i+1}. ${esc(q[0])}</legend>${q[1].map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}"><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}<div class="form-error" id="categoryQuizError"></div><button class="btn primary" type="submit">Check my answers</button></form></section>`)}
function handleCategoryQuiz(e){e.preventDefault();const p=currentProvider(),m=categoryModuleFor(p),t=trainingState(),fd=new FormData(e.currentTarget);let score=0,criticalOk=true;for(let i=0;i<m.questions.length;i++){if(fd.get(`q${i}`)===null){$('#categoryQuizError').textContent='Answer each question first.';$('#categoryQuizError').classList.add('show');return}const correct=Number(fd.get(`q${i}`))===m.questions[i][2];if(correct)score++;if([0,1].includes(i)&&!correct)criticalOk=false}if(score/m.questions.length>=.8&&criticalOk){t.categoryPassed=t.categoryPassed||{};t.categoryPassed[p.category]=true;persist();toast(`${m.title} passed ✓`);nav('finalReadyIntro')}else{toast(criticalOk?'Nearly there — review the food section and try again':'Nearly there — the allergen and verification points must be correct');t.categoryScreen=0;persist();nav('categoryReady')}}
async function compressPortfolioImage(file){if(!file||!file.type.startsWith('image/'))throw new Error('Choose an image file');if(file.size>5*1024*1024)throw new Error('Choose an image under 5 MB');const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const max=900,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.72))};img.onerror=reject;img.src=data})}
function deleteAccountModal(){const a=currentAccount();if(!a)return;formModal('Delete my account',`<div class="danger-note"><b>This locks your Neighbourly account immediately.</b><span>If you are a provider, your profile is hidden from search straight away. You will be signed out on this device and your other Neighbourly sessions will be revoked.</span></div><p class="muted">Some transaction, payment, fraud-prevention or safety records may need to be retained or anonymised for legal, security and dispute-handling reasons rather than erased instantly.</p><div class="field"><label>Why are you leaving? (optional)<textarea name="reason" maxlength="500"></textarea></label></div><label class="check"><input name="confirm" type="checkbox" required><span>I understand that requesting deletion will immediately make my account unavailable.</span></label><button class="btn danger" type="submit">Request account deletion</button>`,async fd=>{if(!fd.get('confirm')){toast('Please confirm before continuing');return}if(!a.serverBacked){toast('Account deletion is available on production accounts');return}try{await window.NeighbourlyAPI.requestAccountDeletion(String(fd.get('reason')||''));closeModal();await signOut();toast('Your deletion request has been recorded')}catch(e){console.error('Deletion request failed',e);toast(e?.message||'Could not request account deletion')}})}
function profilePhotoModal(){const a=currentAccount(),p=currentProvider();if(!a)return;const provider=!!p;formModal(provider?'Profile photo or business logo':'Profile photo',`${provider?`<p class="muted">Choose either a clear portrait of yourself or your genuine business logo. Portraits should be centred, professional and suitable for Neighbourly’s clean ivory profile treatment — no beach/car/party selfies, group photos, sunglasses hiding the face or heavy filters.</p><div class="field"><label>Image type<select name="photoType" required><option value="">Choose one</option><option value="person">My portrait</option><option value="business_logo">My business logo</option></select></label></div>`:`<p class="muted">Your profile photo is optional and is not publicly browseable. Providers only see it when there is a legitimate booking relationship.</p>`}<div class="field"><label>Image<input name="photo" type="file" accept="image/jpeg,image/png" required></label></div><button class="btn primary" type="submit">Send for review</button>`,async fd=>{const file=fd.get('photo'),type=provider?String(fd.get('photoType')||''):null;if(provider&&!type){toast('Choose portrait or business logo');return}if(a.serverBacked){try{await window.NeighbourlyAPI.uploadProfilePhoto(file,type);closeModal();await syncMyMedia();render();toast('Profile image sent for review ✓')}catch(e){toast(e?.message||'Could not upload that image')}return}toast('Profile photos are available on production accounts')})}
function addPortfolioPhotoModal(){const p=currentProvider();if(!p)return;if((p.gallery||[]).filter(x=>x.reviewStatus!=='archived').length>=12){toast('Work gallery is full');return}formModal('Add work photo',`<p class="muted">Use a clear, well-lit photo of your actual work. White or neutral backgrounds are preferred for products, but real service settings are welcome when they help show the result.</p><div class="field"><label>Photo<input name="photo" type="file" accept="image/jpeg,image/png" required></label></div><div class="field"><label>Short caption<input name="caption" maxlength="160" placeholder="e.g. Kitchen deep clean"></label></div><div class="field"><label>Photo setting<select name="background"><option value="white">White background</option><option value="neutral">Plain / neutral background</option><option value="real_setting">Real service setting</option><option value="mixed">Mixed background</option></select></label></div><label class="check"><input name="permission" type="checkbox" required><span>This image is mine to share and does not expose customer faces, addresses, documents or personal information without permission.</span></label><button class="btn primary" type="submit">Send for review</button>`,async fd=>{const file=fd.get('photo');if(!fd.get('permission')){toast('Confirm the photo privacy rule first');return}if(p.serverBacked){try{await window.NeighbourlyAPI.uploadPortfolioImage(file,{caption:String(fd.get('caption')||'').trim(),background:String(fd.get('background')||'unknown')});closeModal();await syncMyMedia();render();toast('Photo sent for review ✓')}catch(e){toast(e?.message||'Could not upload that photo')}return}try{const dataUrl=await compressPortfolioImage(file);p.gallery=p.gallery||[];p.gallery.push({id:uid('photo'),dataUrl,caption:fd.get('caption').trim(),createdAt:Date.now()});persist();closeModal();render();toast('Work photo added ✓')}catch(e){toast(e.message||'Could not add that photo')}})}
function deletePortfolioPhoto(id){const p=currentProvider();if(!p)return;modal('Remove this work photo?','This removes the photo from your Neighbourly gallery.','Remove photo',async()=>{const item=(p.gallery||[]).find(x=>x.id===id);if(item?.serverBacked){try{await window.NeighbourlyAPI.manageMedia({action:'remove',mediaType:'portfolio',id});await syncMyMedia();render();toast('Work photo removed')}catch(e){toast('Could not remove that photo')}return}p.gallery=(p.gallery||[]).filter(x=>x.id!==id);persist();render();toast('Work photo removed')})}
function htmlModal(title,html,onReady=null){closeModal();const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="close-row"><h2>${esc(title)}</h2><button type="button" class="modal-close" aria-label="Close"><span aria-hidden="true">×</span><small>Close</small></button></div><div class="modal-html">${html}</div></div>`;document.body.appendChild(wrap);wrap.querySelector('.close-row button').onclick=closeModal;wrap.onclick=e=>{if(e.target===wrap)closeModal()};document.addEventListener('keydown',escapeModal);onReady?.()}

function quickHelp(){const home=homeRoute(),guide=state.role==='customer'?'customerTour':state.role==='provider'?'providerFeatures':null;htmlModal('Need a hand?',`<p class="muted">Choose what you need. You can always get back home from here.</p><div class="quick-help-actions"><button class="btn primary" id="quickHome">${navIcon('home')}<span>Go to home</span></button><button class="btn secondary" id="quickGuide">${navIcon('help')}<span>${guide?'Show me how Neighbourly works':'How Neighbourly works'}</span></button>${state.role&&state.role!=='admin'?`<button class="btn secondary" id="quickSupport">${navIcon('help')}<span>Sisters Help Desk</span></button>`:''}</div>`,()=>{$('#quickHome')?.addEventListener('click',()=>{closeModal();nav(home)});$('#quickGuide')?.addEventListener('click',()=>{closeModal();if(guide)nav(guide);else modal('How Neighbourly works','Neighbourly helps customers find local service providers, manage service requests, discover community events and get human support. Providers apply, complete Neighbourly Ready and pass appropriate verification before going live.')});$('#quickSupport')?.addEventListener('click',()=>{closeModal();nav('helpDesk')})})}

function confirmPendingCancel(id){const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='awaiting')return;modal('Cancel this request?','The provider will no longer be able to accept it. You can request the service again later.','Yes, cancel request',async()=>{if(r.serverBacked){await runServerServiceAction(r,'cancel',{reason:'Customer cancelled before acceptance'});toast('Request cancelled');return}r.status='cancelled';persist();render();toast('Request cancelled')})}
function confirmProviderAccept(id){const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='awaiting')return;if(r.pricingModeAtBooking!=='fixed_menu'){quoteProviderRequest(id);return}modal('Accept this fixed-price booking?',`The customer already agreed to the listed price. Accept only if you can do the work on the requested date. The exact address is shared after acceptance.`,'Accept & book',async()=>{if(r.serverBacked){await runServerServiceAction(r,'accept');toast('Fixed-price booking accepted ✓');return}r.status='accepted';r.serviceCode=code4();persist();render();toast('Booked — Service Code created ✓')})}
function quoteProviderRequest(id){const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='awaiting'||r.pricingModeAtBooking==='fixed_menu')return;formModal('Quote this job',`<p class="muted">Send the exact price the customer must accept before the booking becomes active.</p><div class="field"><label>Exact price (R)<input name="amount" type="number" min="0" step="1" required placeholder="e.g. 650"></label></div><button class="btn primary" type="submit">Send quote</button>`,async fd=>{const rand=Number(fd.get('amount'));if(!Number.isFinite(rand)||rand<0){toast('Enter a valid price');return}const cents=Math.round(rand*100);if(r.serverBacked){const handled=await runServerServiceAction(r,'quote',{basePriceCents:cents});if(handled){closeModal();toast('Quote sent ✓')}return}r.status='quoted';r.expectedPrice=`R${rand.toFixed(0)}`;persist();closeModal();render();toast('Quote sent ✓')})}
function acceptCustomerQuote(id){const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='quoted')return;modal('Accept this quoted price?',`By accepting, you agree to the provider’s quoted price for this service. The booking then becomes active.`,'Accept price',async()=>{if(r.serverBacked){await runServerServiceAction(r,'accept_quote');toast('Quoted price accepted ✓');return}r.status='accepted';persist();render();toast('Booking accepted ✓')})}
function cancelQuotedRequest(id){const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='quoted')return;modal('Cancel this quote?',`The booking will not go ahead. You can send a new request later if you still need the service.`,'Cancel request',async()=>{if(r.serverBacked){await runServerServiceAction(r,'cancel',{reason:'Quote declined or cancelled before acceptance'});toast('Quote cancelled');return}r.status='cancelled';persist();render();toast('Quote cancelled')})}
function confirmProviderDecline(id){const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='awaiting')return;modal('Decline this request?','That’s okay — a polite no is better than accepting work you cannot do. The customer will see that you’re unavailable for this one.','Decline request',async()=>{if(r.serverBacked){await runServerServiceAction(r,'decline');toast('Request declined');return}r.status='declined';persist();render();toast('Request declined')})}
function confirmCustomerComplete(id){const r=state.requests.find(x=>x.id===id);if(!r||!r.providerMarkedDone||!['accepted','in_progress'].includes(r.status))return;modal('Is the service complete?','Only confirm once the agreed work is finished. You’ll be able to leave a review afterwards.','Yes, all wrapped up',async()=>{if(r.serverBacked){await runServerServiceAction(r,'confirm_complete');toast('Service completed ✓');return}r.status='completed';persist();render();toast('Service completed ✓')})}

