function trainingBack(){const t=trainingState();if(t.screen>0)t.screen--;else if(t.section>0){t.section--;t.screen=trainingSections[t.section].screens.length-1}persist();nav('providerReady')}
function trainingNext(){const t=trainingState(),sec=trainingSections[t.section];if(t.screen<sec.screens.length-1){t.screen++;persist();nav('providerReady')}else nav('sectionQuiz')}
function nextTrainingSection(){const t=trainingState();if(t.section<trainingSections.length-1){t.section++;t.screen=0;persist();nav('providerReady')}else{const p=currentProvider();if(categoryModuleFor(p)&&!t.categoryPassed?.[p.category])nav('categoryReady');else nav('finalReadyIntro')}}
function retrySection(){const t=trainingState();t.screen=0;persist();nav('providerReady')}
function finishReady(){const p=currentProvider(),t=trainingState();if(!p||!t.finalPassed)return;p.onboardingPassed=true;p.applicationStatus='ready_for_review';p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:'Neighbourly Ready completed — sent to Sisters Help Desk for review'});persist();nav('providerHome');toast('You’re Neighbourly Ready ✓')}
async function showProvider(id){const p=state.providers.find(x=>x.providerId===id),a=currentAccount();if(!p)return;let media=null;if(p.serverBacked&&p.serverUserId&&window.NeighbourlyAPI?.configured){try{media=await window.NeighbourlyAPI.getProviderGallery(p.serverUserId)}catch(e){console.error('Provider gallery failed',e)}}const blocked=customerBlockedProvider(a,p),gallery=media?.images??(p.gallery||[]).filter(x=>!x.reviewStatus||x.reviewStatus==='approved'),photos=gallery.map(x=>`<figure><img src="${esc(x.url||x.dataUrl||'')}" alt="Provider work example"><figcaption>${esc(x.caption||'Work example')}</figcaption></figure>`).join(''),photoUrl=media?.profile_photo_url||p.profilePhotoUrl||'',photoType=media?.profile_photo_type||p.profilePhotoType||'person',profileImage=photoUrl?`<div class="public-provider-photo ${photoType==='business_logo'?'logo':'portrait'}"><img src="${esc(photoUrl)}" alt="${photoType==='business_logo'?`${esc(p.name)} business logo`:`${esc(p.name)} profile photo`}"></div>`:'';htmlModal(`${esc(p.name)} · ${esc(p.service)}`,`${profileImage}<p class="muted">${esc(p.about)}</p><div class="provider-meta"><span>Provider ID: <b>${esc(p.providerId)}</b></span>${p.identityVerified?'<span>✓ Identity confirmed</span>':''}<span>${esc((p.areas||[]).join(', '))}</span><span>${esc(p.availability)}</span><span>${moneySafe(p.price)}</span><span>★ ${esc(p.rating)} (${esc(p.reviews)})</span></div><div class="badge-row">${(p.badges||[]).map(b=>`<span class="trust-badge">${esc(b)}</span>`).join('')}</div>${photos?`<h3>Work gallery</h3><div class="work-gallery public">${photos}</div>`:''}<div class="card-actions"><button class="btn primary" id="profileRequest" ${p.paused||p.status!=='approved'||blocked?'disabled':''}>${blocked?'Provider blocked':p.paused?'Taking a breather':'Request service'}</button><button class="btn secondary" id="profileShare">Share provider</button>${state.role==='customer'?`<button class="btn secondary" id="profileReport">Report provider</button><button class="btn ghost" id="profileBlock">${blocked?'Unblock provider':'Block provider'}</button>`:''}</div>`,()=>{$('#profileRequest')?.addEventListener('click',()=>{closeModal();requestModal(id)});$('#profileShare')?.addEventListener('click',()=>shareProviderProfile(id));$('#profileReport')?.addEventListener('click',()=>{closeModal();reportModal({providerId:id})});$('#profileBlock')?.addEventListener('click',()=>{closeModal();toggleProviderBlock(id)})})}
function requestModal(providerId){const p=state.providers.find(x=>x.providerId===providerId),a=currentAccount();if(!p||!a)return;if(customerBlockedProvider(a,p)){modal('Provider blocked','Unblock this provider from their profile before sending a new request.');return}if(providerBlockedCustomer(p,a)){modal('Request unavailable','This provider is not available for new requests from this account. The Sisters Help Desk can help if you believe this is an error.');return}if(p.status!=='approved'||p.paused||p.hideFromSearch){modal('Not accepting new requests',p.pauseReturn?`This provider is taking a breather and plans to return from ${dateText(p.pauseReturn)}.`:'This provider is not accepting new requests right now. You can keep them in Favourites for later.');return}if(a.accountStatus==='restricted'){modal('Account temporarily restricted','You can still view Neighbourly and contact the Sisters Help Desk, but new service requests are paused while this restriction is active.');return}if(!a.emailVerified||!a.mobileVerified){modal('Contact check needed','Before a real-world service request can be sent, confirm your email and mobile number.','Go to profile',()=>nav('profile'));return}if(!a.identityVerified){modal('Identity check needed','Before a real-world service request can be sent, customers need identity confirmation. Neighbourly uses secure identity verification and does not expose your ID to providers.','Go to profile',()=>nav('profile'));return}const today=new Date().toISOString().slice(0,10),fixed=p.pricingMode==='fixed_menu',from=p.pricingMode==='from_price',items=(p.priceItems||[]).filter(x=>x.active!==false);if(fixed&&!items.length){modal('Price list unavailable','This provider’s price list is not available right now. Please try again later.');return}const pricingBlock=fixed?`<div class="field"><label>Choose a service / price<select name="priceItem" required><option value="">Choose one</option>${items.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — R${(Number(x.price_cents||0)/100).toFixed(0)}</option>`).join('')}</select><small>The listed price is fixed. The provider still needs to accept availability before your booking becomes active.</small></label></div>`:from?`<div class="soft-note"><b>${moneySafe(p.price)}</b><span>The provider will send the exact price for this job. You choose whether to accept it.</span></div>`:`<div class="soft-note"><b>Quote required</b><span>The provider will review your request and send an exact price. You choose whether to accept it.</span></div>`;formModal(fixed?'Request a fixed-price service':'Request a quote',`<div class="scope-preview"><small>Service request</small><h3>${esc(p.service)}</h3><span>${esc(p.name)}</span></div>${pricingBlock}<div class="field"><label>Preferred date<input name="date" type="date" min="${today}" required></label></div><div class="field"><label>Service address<input name="address" maxlength="160" required placeholder="Where should the provider come?"><small>The provider sees your neighbourhood first. The exact address is shown only after the booking is accepted.</small></label></div><div class="field"><label>What do you need done?<textarea name="scope" maxlength="400" required placeholder="Describe the work clearly enough for the provider to decide."></textarea></label></div><label class="check"><input name="scopeConfirm" type="checkbox" required><span>${fixed?'I’ve checked the selected service, listed price and requested date.':'I understand the exact price is only agreed once I accept the provider’s quote in Neighbourly.'}</span></label>${connectionNote(true)}<button class="btn primary" type="submit">${fixed?'Send fixed-price request':'Request quote'}</button>`,async fd=>{const d=new Date(`${fd.get('date')}T12:00:00`),address=fd.get('address').trim(),scope=fd.get('scope').trim(),priceItemId=fixed?String(fd.get('priceItem')||''):null;if(isNaN(d)||d.getTime()<new Date(`${today}T00:00:00`).getTime()||!address||!scope||!fd.get('scopeConfirm')||(fixed&&!priceItemId)){toast('Check the date, address and service details before sending');return}if(a.serverBacked&&p.serverBacked&&p.serverUserId){try{await window.NeighbourlyAPI.createOrder({providerUserId:p.serverUserId,serviceName:p.service,scope,serviceAddress:address,scheduledAt:d.toISOString(),priceItemId});closeModal();await syncServerOrders();toast(fixed?'Fixed-price request sent ✓':'Quote request sent ✓');setTimeout(()=>nav('customerServices'),250);return}catch(e){console.error('Request creation failed',e);toast(e?.message||'Could not send this request. Try again.');return}}state.requests.push({id:uid('req'),providerId,providerName:p.name,customerId:a.id,customerName:`${a.first} ${a.last}`,service:p.service,date:fd.get('date'),serviceAddress:address,scope,expectedPrice:fixed?(items.find(x=>x.id===priceItemId)?`R${(items.find(x=>x.id===priceItemId).price_cents/100).toFixed(0)}`:''):p.price,note:scope,status:'awaiting',pricingModeAtBooking:p.pricingMode,createdAt:Date.now(),customerRating:null,extraWork:null,messages:[]});persist();closeModal();toast('Request sent ✓');setTimeout(()=>nav('customerServices'),250)})}
function refreshPerformanceBadges(p){if(!p)return;p.badges=p.badges||[];const highly=(p.reviews||0)>=10&&(p.rating||0)>=4.7;if(highly&&!p.badges.includes('Highly Rated'))p.badges.push('Highly Rated');if(!highly)p.badges=p.badges.filter(b=>b!=='Highly Rated')}
function ratingModal(requestId){formModal('How did it go?',`<p class="muted">Your honest feedback helps the neighbourhood.</p><div class="field"><label>Rating<select name="rating" required><option value="">Choose stars</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)} ${n}/5</option>`).join('')}</select></label></div><div class="field"><label>Quick tags (optional)</label><div class="tag-checks"><label><input type="checkbox" name="tag" value="On time"> On time</label><label><input type="checkbox" name="tag" value="Friendly"> Friendly</label><label><input type="checkbox" name="tag" value="Great work"> Great work</label><label><input type="checkbox" name="tag" value="Good value"> Good value</label></div></div><div class="field"><label>Short review<textarea name="review" maxlength="280"></textarea></label></div><button class="btn primary" type="submit">Share my review</button>`,fd=>{const r=state.requests.find(x=>x.id===requestId);if(!r||!fd.get('rating'))return;r.customerRating=Number(fd.get('rating'));r.review=fd.get('review').trim();r.reviewTags=fd.getAll('tag');const p=state.providers.find(x=>x.providerId===r.providerId);if(p){const total=p.rating*p.reviews+r.customerRating;p.reviews+=1;p.rating=Math.round((total/p.reviews)*10)/10;refreshPerformanceBadges(p)}persist();closeModal();render();toast('Thanks — review shared ♥')})}
function toggleCustomerFav(customerId){const p=currentProvider();if(!p)return;const i=state.favourites.customers.findIndex(x=>x.providerId===p.providerId&&x.customerId===customerId);if(i>=0)state.favourites.customers.splice(i,1);else state.favourites.customers.push({providerId:p.providerId,customerId});persist();render();toast(i>=0?'Removed from favourites':'Favourite customer saved ♥')}
function toggleProviderBlock(providerId){const a=currentAccount(),p=state.providers.find(x=>x.providerId===providerId);if(!a||a.role!=='customer'||!p)return;const i=(state.blocks||[]).findIndex(b=>b.blockerId===a.id&&b.blockedProviderId===providerId);if(i>=0){state.blocks.splice(i,1);persist();render();toast('Provider unblocked');return}modal('Block provider','Blocking stops this provider appearing in your Explore and Favourites and prevents new requests. Existing service history stays available. You can unblock them later.','Block provider',()=>{state.blocks=state.blocks||[];state.blocks.push({id:uid('block'),blockerId:a.id,blockedProviderId:providerId,createdAt:Date.now()});state.favourites.providers=state.favourites.providers.filter(x=>!(x.customerId===a.id&&x.providerId===providerId));persist();render();toast('Provider blocked')})}
function toggleCustomerBlock(customerId){const p=currentProvider(),c=state.accounts.find(a=>a.id===customerId);if(!p||!c)return;const i=(state.blocks||[]).findIndex(b=>b.blockerProviderId===p.providerId&&b.blockedAccountId===customerId);if(i>=0){state.blocks.splice(i,1);persist();render();toast('Customer unblocked');return}modal('Block customer','Blocking prevents this customer from sending you new service requests. Existing service history and records stay available. You can unblock them later.','Block customer',()=>{state.blocks=state.blocks||[];state.blocks.push({id:uid('block'),blockerProviderId:p.providerId,blockedAccountId:customerId,createdAt:Date.now()});persist();render();toast('Customer blocked')})}
function customerNoteModal(customerId){const p=currentProvider(),c=state.accounts.find(a=>a.id===customerId);if(!p||!c)return;const key=`${p.providerId}:${customerId}`,existing=state.customerNotes[key]||{};formModal(`Private note · ${c.first}`,`<div class="privacy-banner"><b>Only you can see this</b><span>Keep notes factual and related to working together. Do not record discriminatory or unnecessarily sensitive personal information.</span></div><div class="field"><label>Would you work with this customer again?<select name="rating"><option value="">Not rated</option>${[5,4,3,2,1].map(n=>`<option value="${n}" ${Number(existing.rating)===n?'selected':''}>${n}/5</option>`).join('')}</select></label></div><div class="field"><label>Private note<textarea name="note" maxlength="300">${esc(existing.note||'')}</textarea></label></div><button class="btn primary" type="submit">Save private note</button>`,fd=>{state.customerNotes[key]={rating:Number(fd.get('rating'))||null,note:fd.get('note').trim(),updatedAt:Date.now()};persist();closeModal();render();toast('Private note saved')})}
function addExtraModal(requestId){formModal('Add extra work',`<p class="muted">Ask your provider before anything changes.</p><div class="field"><label>What would you like added?<textarea name="description" required maxlength="300"></textarea></label></div><button class="btn primary" type="submit">Send extra work request</button>`,async fd=>{const r=state.requests.find(x=>x.id===requestId);if(!r)return;const description=fd.get('description').trim();if(r.serverBacked){try{await window.NeighbourlyAPI.proposeExtraWork({orderId:r.id,description});closeModal();await syncServerOrders();render();toast('Extra work request sent');return}catch(e){console.error(e);toast('Could not send Extra Work. Try again.');return}}r.extraWork={status:'customer_requested',description,requestedAt:Date.now()};persist();closeModal();render();toast('Extra work request sent')})}

async function acceptExtraProvider(requestId){const r=state.requests.find(x=>x.id===requestId);if(!r?.extraWork)return;if(r.serverBacked){await runServerServiceAction(r,'accept_extra_work',{extraWorkId:r.extraWork.id});toast('Extra work accepted ✓');return}if(r.extraWork.status!=='customer_requested')return;r.extraWork.status='confirmed';r.extraWork.providerAcceptedAt=Date.now();r.extraWork.updatedAt=Date.now();persist();render();toast('Extra work accepted ✓')}

function reviewExtraModal(requestId){const r=state.requests.find(x=>x.id===requestId);if(!r?.extraWork)return;formModal('Review extra work',`<p class="muted">${esc(r.extraWork.description)}</p><div class="field"><label>Extra cost (R)<input name="cost" type="number" min="0" step="1" required></label></div><div class="field"><label>Any updated timing or note?<textarea name="note" maxlength="240"></textarea></label></div><button class="btn primary" type="submit">Send change for customer confirmation</button>`,fd=>{r.extraWork.status='provider_proposed';r.extraWork.addedCost=Number(fd.get('cost'))||0;r.extraWork.providerNote=fd.get('note').trim();persist();closeModal();render();toast('Sent to customer for confirmation')})}
async function setExtraStatus(id,status,msg){const r=state.requests.find(x=>x.id===id),a=currentAccount();if(!r?.extraWork)return;if(r.serverBacked){const action=status==='confirmed'?'accept_extra_work':'decline_extra_work';await runServerServiceAction(r,action,{extraWorkId:r.extraWork.id});toast(msg);return}r.extraWork.status=status;r.extraWork.updatedAt=Date.now();if(status==='confirmed')r.extraWork.customerConfirmedAt=Date.now();if(status==='declined')r.extraWork.declinedBy=a?.role||'member';persist();render();toast(msg)}
function safetyModal(requestId){const r=state.requests.find(x=>x.id===requestId),a=currentAccount();if(!r||!a)return;const timer=(r.safetyTimers||{})[a.id],contact=a.trustedContact;formModal('Service safety',`<div class="privacy-banner"><b>Service Code</b><span>Use this with the booking details to confirm the correct service meeting.</span></div><div class="service-code">${esc(r.serviceCode||'----')}</div>${timer?`<div class="${timer.overdue&&!timer.checkedOut?'danger-note':'soft-note'}">${timer.checkedOut?'Checked out safely ✓':timer.overdue?'Your expected finish time has passed. Please check out when you are safe.':`Expected finish: ${dateText(timer.expectedAt)} · ${shortTime(timer.expectedAt)}`}</div>`:''}<div class="emergency-actions"><button type="button" class="btn danger emergency-btn" data-safety="police">Call police · 10111</button><button type="button" class="btn emergency-sisters" data-safety="sisters">Contact Sisters Help Desk</button></div><div class="stack" style="margin-top:14px"><button type="button" class="btn secondary" data-safety="checkin">${r.checkins?.[a.id]?'Checked in ✓':'Check in'}</button><button type="button" class="btn secondary" data-safety="timer">${timer&&!timer.checkedOut?'Update safety time':'Set expected finish time'}</button><button type="button" class="btn secondary" data-safety="share">Share service details${contact?` with ${esc(contact.name)}`:''}</button>${timer&&!timer.checkedOut?`<button type="button" class="btn primary" data-safety="checkout">Check out safely</button>`:''}<button type="button" class="btn secondary" data-safety="report">Report a problem</button></div><p class="muted">Neighbourly is not an emergency service. If someone is in immediate danger, contact appropriate emergency help first. Safety timers in this prototype are checked when the app is open; production will use secure notifications.</p>`,()=>{});$$('[data-safety]').forEach(b=>b.onclick=async()=>{const action=b.dataset.safety;if(action==='police'){closeModal();emergencyAction(requestId,'police')}else if(action==='sisters'){closeModal();emergencyAction(requestId,'sisters')}else if(action==='checkin'){r.checkins=r.checkins||{};r.checkins[a.id]=Date.now();if(a.role==='provider'&&r.status==='accepted')r.status='in_progress';persist();closeModal();render();toast('Checked in ✓')}else if(action==='timer'){closeModal();setSafetyTimerModal(requestId)}else if(action==='share'){await shareServiceDetails(requestId)}else if(action==='checkout'){r.safetyTimers=r.safetyTimers||{};if(r.safetyTimers[a.id]){r.safetyTimers[a.id].checkedOut=true;r.safetyTimers[a.id].checkedOutAt=Date.now();r.safetyTimers[a.id].overdue=false}persist();closeModal();render();toast('Checked out safely ✓')}else{closeModal();reportModal({requestId})}})}
function pauseProviderModal(){const p=currentProvider();if(!p)return;if(p.membershipBreakUntil&&new Date(p.membershipBreakUntil).getTime()>Date.now()){toast('Your membership break controls availability until your return date.');return}if(p.paused){p.paused=false;p.pauseReturn=null;p.awayMessage=null;p.hideFromSearch=p.status!=='approved';persist();render();toast('Back in the neighbourhood ✓');return}formModal('Pause availability',`<p class="muted">Need a breather? Pause new requests for a while. Your profile is removed from Explore, while customers who already saved you can still find you in Favourites.</p><div class="field"><label>Return date (optional)<input name="return" type="date"></label></div><div class="field"><label>Away message (optional)<textarea name="message" maxlength="140" placeholder="e.g. Taking a few days off — back soon."></textarea></label></div><button class="btn primary" type="submit">Pause availability</button>`,fd=>{p.paused=true;p.pauseReturn=fd.get('return')||null;p.awayMessage=fd.get('message').trim()||null;p.hideFromSearch=true;persist();closeModal();render();toast('Taking a breather — availability paused')})}
async function createPromotionModal(){const p=currentProvider();if(!p||p.boosts<1)return;if(p.status!=='approved'||p.paused||p.membershipStatus==='break'||p.reverificationDue||!p.identityVerified||!p.credentialVerified||!p.categoryVerified){modal('Boost unavailable','Boosts are available only while your approved profile, membership and required verification are active. Advertising can never bypass trust or safety checks.');return}if(p.serverBacked&&window.NeighbourlyAPI?.configured){try{const b=await window.NeighbourlyAPI.getMyBoostState();state.myBoostState=b;p.boosts=b.balance??p.boosts;persist();const used=b.fair_use?.boosts_used_last_7_days??0,remaining=b.fair_use?.boosts_remaining_this_window??0,next=b.next_eligible_at?dateText(b.next_eligible_at):null,active=b.active_promotion,areas=(b.areas||[]);const areaOptions=areas.map(x=>`<option value="${esc(x.area)}" ${!x.available?'disabled':''}>${esc(x.area)} · ${x.active_slots}/${x.max_slots} promoted places${x.available?'':' · unavailable'}</option>`).join('');const status=active?`<div class="notice"><b>Boost already active</b><span>${esc(active.service_name)} · ${esc(active.area)} until ${dateText(active.ends_at)}</span></div>`:next?`<div class="notice"><b>Fair-use rest period</b><span>Your next Boost can start from ${next}.</span></div>`:`<div class="notice"><b>${remaining} of 3 fair-use Boosts remaining</b><span>You have used ${used} Boost${used===1?'':'s'} in the last 7 days.</span></div>`;formModal('Use a Neighbourly Boost',`${status}<p class="muted">One Boost promotes one real service in one service area for 24 hours. It cannot run on consecutive days. Neighbourly rotates promoted providers fairly, and paid reach never changes ratings, verification or trust.</p><div class="field"><label>Service<input name="service" value="${esc(b.service_name||p.service)}" readonly></label></div><div class="field"><label>Area<select name="area" required>${areaOptions}</select></label></div><button class="btn primary" type="submit" ${active||next||remaining<1||!areas.some(x=>x.available)?'disabled':''}>Use 1 Boost for 24 hours</button>`,async fd=>{try{await window.NeighbourlyAPI.activateBoost({serviceName:b.service_name||p.service,area:fd.get('area')});const refreshed=await window.NeighbourlyAPI.getMyBoostState();state.myBoostState=refreshed;p.boosts=refreshed.balance??Math.max(0,p.boosts-1);persist();closeModal();render();toast('Boost live for 24 hours · fair rotation active')}catch(e){console.error('Boost activation failed',e);toast(e?.message||'Could not activate this Boost')}});return}catch(e){console.error('Boost state failed',e);toast('Could not load Boost availability. Please try again.');return}}formModal('Use a Neighbourly Boost',`<p class="muted">Prototype mode: promote one service in one area for 24 hours. Paid placements are clearly marked Promoted.</p><div class="field"><label>Service<input name="service" value="${esc(p.service)}" required></label></div><div class="field"><label>Area<select name="area">${(p.areas||[]).map(a=>`<option>${esc(a)}</option>`).join('')}</select></label></div><button class="btn primary" type="submit">Use 1 Boost</button>`,fd=>{p.boosts--;state.promotions.push({id:uid('promo'),providerId:p.providerId,service:fd.get('service'),area:fd.get('area'),createdAt:Date.now(),expiresAt:Date.now()+24*60*60*1000});persist();closeModal();render();toast('Prototype Boost live for 24 hours · clearly marked Promoted')})}
function addEventModal(){const a=currentAccount();formModal('List a community event',`<div class="field"><label>Event name<input name="title" required maxlength="90"></label></div><div class="field two"><label>Area<input name="area" required value="${esc(a?.area||'')}"></label><label>Category<select name="category"><option>Community</option><option>Market</option><option>Family</option><option>Learning</option><option>Sport</option><option>Faith & community</option><option>Other</option></select></label></div><div class="field"><label>Date and time<input name="date" type="datetime-local" required></label></div><div class="field"><label>Details<textarea name="details" required maxlength="400"></textarea></label></div><label class="check"><input name="accurate" type="checkbox" required><span>I confirm this listing is genuine and the details are accurate to the best of my knowledge.</span></label><button class="btn primary" type="submit">List event</button>`,fd=>{const dt=new Date(fd.get('date'));if(!fd.get('title')||!fd.get('accurate')||isNaN(dt)||dt.getTime()<Date.now()){toast('Complete the event details and choose a future date');return}state.events.push({id:uid('event'),title:fd.get('title').trim(),area:fd.get('area').trim(),category:fd.get('category'),startsAt:dt.toISOString(),details:fd.get('details').trim(),createdBy:a?`${a.first} ${a.last}`:'Sisters Help Desk',createdById:a?.id||null,status:'active'});persist();closeModal();render();toast('Community event listed ✓')})}
function postUpdateModal(){formModal('Post a Neighbourly update',`<div class="field"><label>Update type<select name="type"><option value="info">Important note</option><option value="issue">Service issue / maintenance</option><option value="good">Good news</option></select></label></div><div class="field"><label>Title<input name="title" required maxlength="90"></label></div><div class="field"><label>Message<textarea name="body" required maxlength="500"></textarea></label></div><button class="btn primary" type="submit">Post update</button>`,fd=>{state.updates.push({id:uid('up'),type:fd.get('type'),title:fd.get('title').trim(),body:fd.get('body').trim(),createdAt:Date.now()});persist();closeModal();render();toast('Neighbourly update posted')})}
async function emergencyAction(requestId,action){const r=state.requests.find(x=>x.id===requestId),a=currentAccount();if(!r||!a)return;const police=action==='police';if(police){if(window.NeighbourlyAPI?.configured){window.NeighbourlyAPI.createEmergencyCase({orderId:r.id,action}).then(()=>toast('Critical Sisters safety case created.')).catch(e=>{console.error('Emergency case sync failed',e);toast('10111 opened. The Sisters safety case could not sync—please contact the Help Desk when safe.')});}else{const incident={id:uid('emergency'),requestId:r.id,reason:'Emergency police action',details:`Emergency action from ${a.role} during ${r.service}. Service/order ${r.id}.`,fromName:`${a.first} ${a.last}`,fromId:a.id,targetType:'service',targetId:r.id,targetLabel:`${r.service} · ${r.id}`,status:'awaiting',priority:'critical',safePhone:a.phone||null,safeEmail:a.email||null,createdAt:Date.now()};state.reports.push(incident);persist();}location.href=`tel:${SAPS_EMERGENCY_NUMBER}`;return;}if(window.NeighbourlyAPI?.configured){try{await window.NeighbourlyAPI.createEmergencyCase({orderId:r.id,action});toast('Urgent safety case sent to Sisters Help Desk');return}catch(e){console.error('Emergency case sync failed',e);toast('Could not send the urgent safety case. Please try Sisters Help Desk again.');return}}const incident={id:uid('emergency'),requestId:r.id,reason:'Urgent Sisters safety help',details:`Emergency action from ${a.role} during ${r.service}. Service/order ${r.id}.`,fromName:`${a.first} ${a.last}`,fromId:a.id,targetType:'service',targetId:r.id,targetLabel:`${r.service} · ${r.id}`,status:'awaiting',priority:'critical',safePhone:a.phone||null,safeEmail:a.email||null,createdAt:Date.now()};state.reports.push(incident);persist();toast('Urgent safety report sent to Sisters Help Desk');setTimeout(()=>reportModal({requestId}),250)}
function reportModal(context={}){const a=currentAccount(),targets=reportTargetOptions(a,context),selected=reportContextValue(context,a);formModal('Sisters Help Desk',`<div class="support-modal-head"><img src="sisters-help-desk.webp" alt="Illustration of the Sisters Help Desk"><div><span class="support-kicker">Real people. Real support.</span><p>Tell us what’s going on. You can disagree, complain or ask questions — we just ask everyone to communicate respectfully.</p></div></div><div class="field"><label>Who or what is this about?<select name="target" required>${targets.map(x=>`<option value="${esc(x.value)}" ${x.value===selected?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label></div><div class="field"><label>What can we help with?<select name="reason" required><option value="">Choose what fits best</option><option>Order issue</option><option>Service issue</option><option>Payment or refund issue</option><option>No-show or cancellation</option><option>Food safety or quality concern</option><option>Something feels unsafe or wrong</option><option>App or account issue</option><option>Community event issue</option><option>General question</option><option>Something else</option></select><small>Choose “Something feels unsafe or wrong” for fraud, scams, harassment, threats, discrimination, sexual misconduct or anything else that worries you.</small></label></div><div class="field"><label>Tell us what happened<textarea name="details" required maxlength="700" placeholder="Just tell us what we need to understand."></textarea></label></div><button class="btn primary" type="submit">Send to Sisters Help Desk</button>`,async fd=>{if(!fd.get('reason')||!fd.get('details').trim())return;const target=resolveReportTarget(fd.get('target'));if(a?.serverBacked&&window.NeighbourlyAPI?.configured){try{const result=await window.NeighbourlyAPI.createSupportCase({reason:fd.get('reason'),details:fd.get('details').trim(),orderId:context.requestId||null,targetUserId:target.accountId||null});closeModal();toast(result.priority==='high'?'Sent to Sisters Help Desk as high priority':'Thanks for telling us. We’ll take a look.');return}catch(e){console.error('Help Desk case failed',e);toast('Could not send this to Sisters Help Desk. Please try again.');return}}state.reports.push({id:uid('rep'),reason:fd.get('reason'),details:fd.get('details').trim(),fromName:a?`${a.first} ${a.last}`:'Neighbour',fromId:a?.id||null,targetType:target.type,targetId:target.id,targetLabel:target.label,targetAccountId:target.accountId||null,targetProviderId:target.providerId||null,status:'awaiting',createdAt:Date.now()});persist();closeModal();toast('Thanks for telling us. We’ll take a look.')})}
function customerSafetyGuide(){modal('Stay safe with Neighbourly',`1. Check who you booked using the profile and Service Code.\n\n2. Keep important arrangements in Neighbourly where practical.\n\n3. Never share your password, banking PIN or OTP.\n\n4. Extra work belongs in the Extra Work flow so both sides agree.\n\n5. If there is immediate crime-related danger, use Call police · 10111. The app also creates a high-priority Sisters safety report with the service details where connectivity allows.\n\n6. Sisters Help Desk — Real people. Real support. — can help with urgent platform safety action, but it is not an emergency service.`)}
function membershipBreakModal(){const p=currentProvider();if(!p)return;if(p.membershipBreakUntil&&new Date(p.membershipBreakUntil).getTime()>Date.now()){modal('End membership break early',`Your membership break is scheduled until ${dateText(p.membershipBreakUntil)}. You can return early without a reactivation fee.`,'Return now',()=>{p.membershipBreakUntil=null;p.membershipStatus='active';p.paused=false;p.hideFromSearch=p.status!=='approved';persist();render();toast('Back in the neighbourhood ✓')});return}const history=(p.membershipBreakHistory||[]).filter(x=>Date.now()-x.startedAt<365*86400000);if(history.length>=2){modal('Membership break limit reached','The working policy allows up to two membership breaks in a rolling 12 months. The Sisters Help Desk can help if there are exceptional circumstances.');return}formModal('Take a membership break',`<p class="muted">Life happens. A membership break keeps your profile, reviews, history and Provider ID safe while your active membership is paused.</p><div class="field"><label>Return date<input name="return" type="date" required></label></div><p class="muted">Up to 60 days, up to twice in 12 months, no reactivation fee. Your profile is removed from active search. In production, billing will pause and resume automatically on the selected date.</p><button class="btn primary" type="submit">Schedule membership break</button>`,fd=>{const d=new Date(`${fd.get('return')}T12:00:00`),max=Date.now()+60*86400000;if(isNaN(d)||d.getTime()<=Date.now()||d.getTime()>max){toast('Choose a return date within 60 days');return}p.membershipBreakHistory=history;p.membershipBreakHistory.push({startedAt:Date.now(),returnAt:d.getTime()});p.membershipBreakUntil=d.toISOString();p.membershipStatus='break';p.paused=true;p.hideFromSearch=true;persist();closeModal();render();toast('Membership break scheduled')})}
function portfolioInfo(){modal('Work gallery','Add up to three genuine work examples with short captions. Do not upload customer faces, home addresses, documents or personal information without permission. Images are compressed and stored only in this browser prototype; production will use secure storage, moderation and reporting.') }
function audit(action,details=''){state.auditLog=state.auditLog||[];state.auditLog.push({t:Date.now(),action,details,actor:'Sisters Help Desk'});persist()}
function showPolicies(){modal('Community, safety & food policies',`NEIGHBOURLY IS A KIND COMMUNITY\nCustomers, providers and the Sisters Help Desk must treat each other with respect. Complaints and disagreement are allowed. Abuse, threats, harassment, discrimination, sexual misconduct, scams and deliberate exploitation are not.\n\nFIRM BUT FAIR\nGuidance, warnings and temporary restrictions are used proportionately. Account removal is the last normal step, but severe or repeated confirmed abuse can justify permanent removal. Permanently removed users may not rejoin. Strong identity matches are reviewed carefully so shared devices, homes or surnames do not create automatic false bans.\n\nFOOD ORDERS\nSupplied food is not returnable simply because someone changed their mind or dislikes the taste. Genuine unsafe, incorrect or materially defective food concerns must be handled fairly and applicable consumer rights remain.\n\nIDENTITY & PRIVACY\nNeighbourly aims to verify both sides before real-world services without exposing ID documents to other users. Production should use secure identity verification and keep only necessary information for as long as needed.\n\nSAFETY\nKeep arrangements in Neighbourly where practical, never share passwords/PINs/OTPs, use Service Codes and report suspicious behaviour. Neighbourly is not an emergency service.\n\nCANCELLATIONS & NO-SHOWS\nBoth sides should cancel as early as reasonably possible. Repeated avoidable cancellations or no-shows can affect reliability status and may lead to proportionate account action. Genuine emergencies should be considered fairly.\n\nPERMANENT REMOVAL & REJOINING\nPermanent removal is reserved for serious or repeated confirmed breaches. A permanently removed person may not simply create a new account. Exact or strong identity matches should be reviewed, while shared addresses, devices, surnames or Wi-Fi alone are not proof. One fair appeal route should exist for mistakes.\n\nSISTERS HELP DESK\nYou may disagree with us, complain or appeal. That is not abuse. We commit to fair treatment, privacy, clear reasons for significant decisions and conflict-of-interest care. Threats, harassment or abuse toward support staff are treated under the same Community Standard.`)}
function demoVerifyContact(){const a=currentAccount();if(!a)return;modal('Prototype contact check','For the real app, Neighbourly will confirm email and mobile with secure verification links/codes. This prototype will only simulate successful confirmation.','Simulate contact confirmation',()=>{a.emailVerified=true;a.mobileVerified=true;persist();render();toast('Email & mobile confirmed ✓')})}
function demoVerifyIdentity(){const a=currentAccount();if(!a)return;modal('Prototype identity check','For the real app, Neighbourly should use a secure identity-verification service with ID + selfie/liveness checks and minimal data retention. This prototype will only simulate a successful check.','Simulate verification',()=>{a.identityVerified=true;const p=currentProvider();if(p)p.identityVerified=true;persist();render();toast('Prototype identity confirmed ✓')})}
function toggleOnboardingHelp(providerId){const p=state.providers.find(x=>x.providerId===providerId);if(!p)return;p.needsOnboardingHelp=!p.needsOnboardingHelp;audit('Onboarding help flag updated',`${p.providerId} · ${p.needsOnboardingHelp?'help requested':'flag cleared'}`);p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:p.needsOnboardingHelp?'Sisters Help Desk added onboarding support':'Onboarding support flag cleared'});persist();render();toast(p.needsOnboardingHelp?'Onboarding help flagged ✓':'Onboarding help flag cleared')}
function scheduleSiteVisitModal(providerId){const p=state.providers.find(x=>x.providerId===providerId);if(!p||!p.siteVisitRequired)return;if(p.status!=='approved'&&p.applicationStatus==='ready_for_review')p.applicationStatus='verification_in_progress';const min=new Date().toISOString().slice(0,10);formModal('Schedule food setup check',`<p class="muted">Choose a practical date for the required verification visit. The provider will see this in their application updates.</p><div class="field"><label>Visit date<input name="date" type="date" min="${min}" value="${p.siteVisitDate?new Date(p.siteVisitDate).toISOString().slice(0,10):''}" required></label></div><button class="btn primary" type="submit">Save visit date</button>`,fd=>{const d=new Date(`${fd.get('date')}T12:00:00`);if(isNaN(d)||d.getTime()<new Date(`${min}T00:00:00`).getTime()){toast('Choose today or a future date');return}p.siteVisitDate=d.toISOString();p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:`Food setup check scheduled for ${dateText(p.siteVisitDate)}`});audit('Site visit scheduled',`${p.providerId} · ${p.siteVisitDate}`);persist();closeModal();render();toast('Visit scheduled ✓')})}
function toggleVerify(providerId,key){const p=state.providers.find(x=>x.providerId===providerId);if(!p)return;p[key]=!p[key];if(p.status!=='approved'&&p.applicationStatus==='ready_for_review')p.applicationStatus='verification_in_progress';if(key==='credentialVerified'){if(p[key]){p.verificationValidUntil=new Date(Date.now()+365*86400000).toISOString();p.reverificationDue=false;p.verificationExpiredLogged=false;if(p.status==='approved'){const trust=p.credentialPath==='qualified'?'Qualified & Verified':p.credentialPath==='registered'?'Registered Professional':'Skilled by Experience';p.badges=p.badges||[];if(!p.badges.includes(trust))p.badges.unshift(trust);p.verified=true}}else{p.verificationValidUntil=null}}audit('Verification updated',`${p.providerId} · ${key} · ${p[key]?'complete':'reopened'}`);p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:`${titleCase(key.replace(/([A-Z])/g,' $1'))} ${p[key]?'completed':'reopened'}`});persist();render()}
function approveProvider(id){const p=state.providers.find(x=>x.providerId===id);if(!p||!eligibleForApproval(p))return;audit('Provider approved',p.providerId);p.status='approved';p.applicationStatus='approved';p.verified=true;if(p.credentialVerified&&!p.verificationValidUntil)p.verificationValidUntil=new Date(Date.now()+365*86400000).toISOString();p.badges=p.badges||[];const trust=p.credentialPath==='qualified'?'Qualified & Verified':p.credentialPath==='registered'?'Registered Professional':'Skilled by Experience';if(!p.badges.includes(trust))p.badges.unshift(trust);if((p.reviews||0)===0&&!p.badges.includes('New to Neighbourly')){p.badges.push('New to Neighbourly');p.newBadgeUntil=new Date(Date.now()+30*86400000).toISOString()}p.applicationUpdates.push({t:Date.now(),text:'Application approved — profile is live'});persist();render();toast(`${p.name} is now live ✓`)}
function changesProvider(id){const p=state.providers.find(x=>x.providerId===id);if(!p)return;audit('Provider changes requested',p.providerId);p.status='changes';p.applicationStatus='changes';p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:'Sisters Help Desk requested changes'});persist();render();toast('Marked as needing changes')}
function declineProviderModal(id){const p=state.providers.find(x=>x.providerId===id);if(!p)return;formModal('Decline provider application',`<p class="muted">This is an application decision, not a Community Standard ban. Record a clear, fair reason the provider can understand.</p><div class="field"><label>Reason<textarea name="reason" maxlength="500" required placeholder="Explain what could not be approved."></textarea></label></div><button class="btn danger" type="submit">Decline application</button>`,fd=>{const reason=fd.get('reason').trim();if(!reason)return;p.status='declined';p.applicationStatus='declined';p.hideFromSearch=true;p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:`Application declined — ${reason}`});audit('Provider application declined',`${p.providerId} · ${reason}`);persist();closeModal();render();toast('Application declined')})}
function confirmRemovalModal(id){const r=state.reports.find(x=>x.id===id);if(!r)return;formModal('Confirm permanent removal',`<div class="danger-note"><b>Last-step action</b><span>Permanent removal should only be used after a fair review for serious or repeated confirmed misconduct. The person will not be permitted to rejoin.</span></div><p class="muted">Target: <b>${esc(r.targetLabel||'Unknown')}</b></p><label class="check"><input name="secondReview" type="checkbox" required><span>A second review has been completed, or an urgent safety reason for proceeding is recorded.</span></label><div class="field"><label>Type REMOVE to confirm<input name="confirm" autocomplete="off" required></label></div><div class="field"><label>Decision note<textarea name="note" maxlength="500" required placeholder="Briefly record why permanent removal is proportionate."></textarea></label></div><button class="btn danger" type="submit">Permanently remove account</button>`,fd=>{if(!fd.get('secondReview')||fd.get('confirm')!=='REMOVE'||!fd.get('note').trim()){toast('Complete the review confirmation and type REMOVE');return}r.decisionNote=fd.get('note').trim();closeModal();reportAction(id,'removal')})}
function reportAction(id,level){const r=state.reports.find(x=>x.id===id);if(!r)return;const labels={guidance:'Guidance provided',warning:'Formal warning issued',final_warning:'Final warning issued',restriction:'7-day temporary restriction applied',removal:'Permanent removal after serious/repeated confirmed breach'},acct=state.accounts.find(a=>a.id===r.targetAccountId),provider=state.providers.find(p=>p.providerId===r.targetProviderId)||(acct?.providerId?state.providers.find(p=>p.providerId===acct.providerId):null);r.status='closed';r.outcome=labels[level];if(acct){acct.enforcementHistory=acct.enforcementHistory||[];acct.enforcementHistory.push({t:Date.now(),level,caseId:r.id})}if(level==='restriction'){const until=Date.now()+7*86400000;if(acct){acct.accountStatus='restricted';acct.restrictionUntil=until}if(provider){provider.previousStatus=provider.status;provider.status='restricted';provider.hideFromSearch=true;provider.restrictionUntil=until}}if(level==='removal'){if(acct){acct.accountStatus='permanently_removed';state.bannedPeople=state.bannedPeople||[];if(!state.bannedPeople.some(b=>b.accountId===acct.id))state.bannedPeople.push({accountId:acct.id,email:acct.email,phone:acct.phone,name:`${acct.first} ${acct.last}`,providerId:acct.providerId||null,previousProviderStatus:provider?.status||null,reason:r.reason,removedAt:Date.now()})}if(provider){provider.previousStatus=provider.status;provider.status='removed';provider.hideFromSearch=true}}audit('Case outcome',`${r.id} · target ${r.targetLabel||'unknown'} · ${labels[level]}`);persist();render();toast(labels[level])}

function closeModal(){window.NeighbourlyAPI?.unsubscribe?.(window.__messageChannel);window.__messageChannel=null;document.querySelector('.modal-backdrop')?.remove();document.removeEventListener('keydown',escapeModal)}
function escapeModal(e){if(e.key==='Escape')closeModal()}
function modal(title,body,actionLabel=null,action=null){closeModal();const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="close-row"><h2>${esc(title)}</h2><button type="button" class="modal-close" aria-label="Close"><span aria-hidden="true">×</span><small>Close</small></button></div><div class="modal-copy">${esc(body).replace(/\n/g,'<br>')}</div>${actionLabel?`<button class="btn primary" id="modalAction">${esc(actionLabel)}</button>`:''}</div>`;document.body.appendChild(wrap);wrap.querySelector('.close-row button').onclick=closeModal;wrap.onclick=e=>{if(e.target===wrap)closeModal()};if(actionLabel)$('#modalAction',wrap).onclick=()=>{closeModal();action?.()};document.addEventListener('keydown',escapeModal)}
function formModal(title,html,onSubmit){closeModal();const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="close-row"><h2>${esc(title)}</h2><button type="button">×</button></div><form class="form modal-form">${html}</form></div>`;document.body.appendChild(wrap);wrap.querySelector('.close-row button').onclick=closeModal;wrap.onclick=e=>{if(e.target===wrap)closeModal()};wrap.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget))};document.addEventListener('keydown',escapeModal)}

async function bootstrapProductionSession(){
 if(!window.NeighbourlyAPI?.configured)return;
 try{
  const session=await window.NeighbourlyAPI.getSession();
  if(!session){const current=currentAccount();if(current?.serverBacked){state.accounts=state.accounts.filter(a=>a.id!==current.id);if(current.providerId)state.providers=state.providers.filter(p=>p.providerId!==current.providerId||!p.serverBacked)}state.role=null;state.currentAccountId=null;persist();render();return}
  const bundle=await window.NeighbourlyAPI.getMyProfile(session.user.id);const a=upsertServerAccount(bundle);state.currentAccountId=a.id;state.role=a.role;if(state.route==='publicHome'||state.route==='loginForm'||state.route==='loginChoice')state.route=a.role==='provider'?'providerHome':'customerHome';persist();await syncServerProviders();await syncMyMedia();await syncMembershipCatalog();await syncServerOrders();await syncServerNotifications();render();startNotificationSubscription();openSharedProviderIfReady();
 }catch(e){console.error('Session bootstrap failed',e);const current=currentAccount();if(current?.serverBacked){state.role=null;state.currentAccountId=null;state.route='publicHome';persist();render()}}
}
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js').catch(()=>{}));
render();
window.addEventListener('load',bootstrapProductionSession);

